Q: Using promises with streams in node.js
A: <p>After a bunch of tries I found a solution which works fine all the time. See JSDoc comments for more info.</p>

<pre><code>/**
 * Streams input to output and resolves only after stream has successfully ended.
 * Closes the output stream in success and error cases.
 * @param input {stream.Readable} Read from
 * @param output {stream.Writable} Write to
 * @return Promise Resolves only after the output stream is "end"ed or "finish"ed.
 */
function promisifiedPipe(input, output) {
    let ended = false;
    function end() {
        if (!ended) {
            ended = true;
            output.close &amp;&amp; output.close();
            input.close &amp;&amp; input.close();
            return true;
        }
    }

    return new Promise((resolve, reject) =&gt; {
        input.pipe(output);
        input.on('error', errorEnding);

        function niceEnding() {
            if (end()) resolve();
        }

        function errorEnding(error) {
            if (end()) reject(error);
        }

        output.on('finish', niceEnding);
        output.on('end', niceEnding);
        output.on('error', errorEnding);
    });
};
</code></pre>

<p>Usage example:</p>

<pre><code>function downloadFile(req, res, next) {
  promisifiedPipe(fs.createReadStream(req.params.file), res).catch(next);
}
</code></pre>

<p><strong>Update.</strong> I've published the above function as a Node module: <a href="http://npm.im/promisified-pipe" rel="noreferrer">http://npm.im/promisified-pipe</a></p>

